@startuml

class Client {
  + Nin
  + Tin
  + Name
  + Address
}

class BicycleModel {
  + Name
  + Type
  + Gears
}

class Bicycle {
  + Number
}

class Store {
  + Name
  + Address
}

class Reservation {
  + Pickup_Day
}

class Rental {
  + Return_Day
}

Client "1" -- "*" Reservation : makes
Reservation "*" -- "1" BicycleModel : for
Reservation "*" -- "1" Store : at
Reservation "1" -- "0..1" Rental : results in

BicycleModel "1" -- "*" Bicycle : has

Store "1" -- "*" Bicycle : contains

@enduml

